import { Parser, ReplacementRules, popKeys } from './parser';
import { Generators, createPromptInfo, createSampler, createModel, createPrompt, PromptInfo, Model } from '../data';
import { ParserError } from '../exceptions';
import { loadJson } from '../utils/json';

const SAMPLER_PARAMS = ['Sampler', 'CFG scale', 'Seed', 'Steps', 'ENSD', 'Schedule type'];

const REPLACEMENT_RULES: ReplacementRules = [['Schedule type', 'scheduler']];

/**
 * Parser for images generated by AUTOMATIC1111's stable-diffusion-webui or similar
 */
export class AUTOMATIC1111Parser extends Parser {
  public readonly generator = Generators.AUTOMATIC1111;

  async parse(parameters: Record<string, any>): Promise<PromptInfo> {
    const parameterString = parameters?.parameters;
    if (typeof parameterString !== 'string') {
      throw new ParserError('error reading parameter string');
    }
    const lines = parameterString.split('\n');

    const { infoIndex, samplerInfo, metadata } = getSamplerInfo(lines);
    const prompts = lines.slice(0, infoIndex).join('\n').split('Negative prompt:');
    if (prompts.length > 2) {
      throw new ParserError('found multiple negative prompts');
    }
    const [prompt, negativePrompt] = [prompts[0], prompts[1] ?? ''].map(p => p.trim());

    if (!('Sampler' in samplerInfo)) {
      throw new ParserError('no sampler found');
    }
    const samplerName = samplerInfo.Sampler;
    delete samplerInfo.Sampler;

    const modelName = metadata.Model;
    const modelHash = metadata['Model hash'];
    delete metadata.Model;
    delete metadata['Model hash'];

    let model: Model | undefined;
    if (modelName || modelHash) {
      model = createModel({ name: modelName, hash: modelHash });
    }

    const sampler = createSampler(samplerName, this.normalizeParameters(samplerInfo, REPLACEMENT_RULES), {
      model,
      prompts: prompt ? [createPrompt(prompt)] : [],
      negativePrompts: negativePrompt ? [createPrompt(negativePrompt)] : [],
    });

    return createPromptInfo(this.generator, [sampler], metadata, parameters);
  }
}

/**
 * Find the line holding the sampler information, searching from the end of the parameter string
 */
function getSamplerInfo(lines: string[]): {
  infoIndex: number;
  samplerInfo: Record<string, any>;
  metadata: Record<string, any>;
} {
  for (let index = lines.length - 1; index >= 0; index--) {
    const metadata = extractMetadata(lines[index]);
    const samplerInfo = Object.fromEntries(popKeys(SAMPLER_PARAMS, metadata));
    if (Object.keys(samplerInfo).length >= 3) {
      return { infoIndex: index, samplerInfo, metadata };
    }
  }

  throw new ParserError('no sampler information found');
}

/**
 * Extract the `key: value` pairs of a parameter line
 */
function extractMetadata(line: string): Record<string, any> {
  const metadata: Record<string, any> = {};

  // try to extract hashes
  const match = /(?:,\s*)?Hashes:\s*(\{[^}]*\})\s*/.exec(line);
  if (match) {
    try {
      metadata.Hashes = loadJson(match[1]);
    } catch {
      // ignore malformed hashes
    }
    line = line.slice(0, match.index) + line.slice(match.index + match[0].length);
  }

  for (const item of line.split(',')) {
    const parts = item.split(':');
    if (parts.length === 2) {
      const [key, value] = parts.map(part => part.trim());
      metadata[key] = value;
    }
  }

  return metadata;
}
